        await safe_edit_query(query,'📣 <b>Broadcast</b>\n\nمتن پیام عمومی را در پیام بعدی بفرست.\nبرای لغو، «لغو» را ارسال کن.',v5_markup([[v5_button('❌ لغو','V5|A|FC')]])); return
